using System;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.InteropServices;using System.Threading;using System.Windows.Forms;using SlopStudio;
class V7GuiTests {
 static BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static List<string> lines=new List<string>();static List<Exception> uiErrors=new List<Exception>();static int failed;static string root;static object Field(object o,string n){for(Type t=o.GetType();t!=null;t=t.BaseType){var f=t.GetField(n,F|BindingFlags.DeclaredOnly);if(f!=null)return f.GetValue(o);}throw new Exception("Missing field "+n);}static object Call(object o,string n,params object[] a){for(Type t=o.GetType();t!=null;t=t.BaseType){var m=t.GetMethods(F|BindingFlags.DeclaredOnly).FirstOrDefault(x=>x.Name==n&&x.GetParameters().Length==a.Length);if(m!=null)return m.Invoke(o,a);}throw new Exception("Missing method "+n);}static void Check(bool b,string s){if(!b)throw new Exception(s);}static void Test(string n,Action a){int errors=uiErrors.Count;try{a();Pump(25);Check(errors==uiErrors.Count,"Unhandled UI exception: "+(uiErrors.Count>errors?uiErrors.Last().ToString():""));lines.Add("PASS "+n);}catch(Exception e){failed++;lines.Add("FAIL "+n+" :: "+e);}}
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);[DllImport("user32.dll")]static extern bool PrintWindow(IntPtr h,IntPtr dc,uint flags);[DllImport("user32.dll")]static extern bool SetKeyboardState(byte[] state);[DllImport("user32.dll")]static extern bool GetKeyboardState(byte[] state);
 static void Pump(int ms){var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(5);}}static void Msg(Control c,int id,int x,int y,int w=0){SendMessage(c.Handle,id,(IntPtr)w,(IntPtr)((y<<16)|(x&65535)));}static void Mouse(Control c,int id,double x,double y,int w=0){float s=DisplayScale.For(c);Msg(c,id,(int)(x*s),(int)(y*s),w);}static void Click(Control c,double x,double y){Mouse(c,0x201,x,y,1);Mouse(c,0x202,x,y);Pump(30);}static void Capture(Form f,string name){Pump(90);using(var b=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(b)){var dc=g.GetHdc();try{if(!PrintWindow(f.Handle,dc,2))throw new Exception("Own-window PrintWindow failed.");}finally{g.ReleaseHdc(dc);}}b.Save(Path.Combine(root,name+".png"));}}
 static void Choose(StudioChoice choice,int index){Click(choice,10,9);var menu=(ContextMenuStrip)Field(choice,"_menu");Check(menu!=null&&menu.Visible,"Choice menu did not open.");Rectangle r=menu.Items[index].Bounds;Msg(menu,0x201,r.X+r.Width/2,r.Y+r.Height/2,1);Msg(menu,0x202,r.X+r.Width/2,r.Y+r.Height/2);Pump(80);}
 static ProjectDocument Project(MainForm f){return (ProjectDocument)Field(f,"_project");}static void CloseMain(MainForm f){((ProjectHistory)Field(f,"_history")).Reset(true);typeof(MainForm).GetField("_closing",F).SetValue(f,true);f.Close();f.Dispose();}
 [STAThread]static int Main(string[] args){root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("SLOPSTUDIO_PROFILE",Path.Combine(root,"profile"));Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);Application.ThreadException+=delegate(object s,ThreadExceptionEventArgs e){uiErrors.Add(e.Exception);};Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);UiText.Load("en-US");var settings=new AppSettings{AudioBackend="WASAPI",InputEndpoint="__unavailable_test_input__"};settings.Integration.QuickStart=false;var locale=LocaleCatalog.Load(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"locales","en-US.json"),"en-US");using(var form=new MainForm(settings,locale,false,null)){form.Show();Pump(200);
 Test("Real native dropdown mouse clicks survive owner disposal after selection",()=>{using(var host=new Form{Text="Menu lifetime regression",ClientSize=new Size(360,150)}){var choice=new StudioChoice{Dock=DockStyle.Top};choice.Items.AddRange(new object[]{"One","Two","Three"});choice.SelectedIndex=0;host.Controls.Add(choice);bool invoked=false;choice.SelectedIndexChanged+=delegate{invoked=true;host.Controls.Remove(choice);choice.Dispose();};host.Show(form);Choose(choice,1);Check(invoked&&choice.IsDisposed,"Selection/disposal workflow did not run.");host.Close();}});
 Test("Preferences driver WASAPI / ASIO / MME and float bounce format use real native menu events",()=>{using(var prefs=new PreferencesForm(settings)){prefs.Show(form);Pump(80);var driver=(StudioChoice)Field(prefs,"_driver");foreach(int i in new[]{2,3,0,1,0}){Choose(driver,i);Check(driver.SelectedIndex==i,"Driver item not selected.");var deviceChoice=(StudioChoice)Field(prefs,"_out");Check(deviceChoice.Items.Count==0||deviceChoice.SelectedItem!=null,"Driver change left an invalid output selection.");}Capture(prefs,"preferences-audio");prefs.Close();}using(var bounce=new AudioExportDialog(Project(form))){bounce.Show(form);Pump(60);var format=(StudioChoice)Field(bounce,"_format");Choose(format,2);Check(format.SelectedIndex==2,"32-bit float did not select.");Capture(bounce,"bounce-32-float");bounce.Close();}});
 var timeline=(TimelineEditor)Field(form,"_timeline");Control canvas=(Control)Field(timeline,"_canvas");
 Test("Ctrl-wheel zooms timeline only; Shift-wheel pans horizontally; pointer anchor stays in view",()=>{timeline.SetZoom(48);timeline.ScrollHorizontalTo(12);Point p=canvas.PointToScreen(new Point(canvas.Width/2,90));int scale=settings.UiScale,zoom=timeline.Zoom;timeline.NavigateWheel(p,120,Keys.Control);Check(timeline.Zoom>zoom&&settings.UiScale==scale,"Editor zoom changed UI scale.");double before=timeline.HorizontalBeat;timeline.NavigateWheel(p,-120,Keys.Shift);Check(timeline.HorizontalBeat>before,"Shift horizontal camera did not move.");byte[] original=new byte[256];GetKeyboardState(original);Point cursor=Cursor.Position;try{var keys=(byte[])original.Clone();keys[17]=128;Cursor.Position=p;Pump(20);SetKeyboardState(keys);var filter=(IMessageFilter)Field(form,"_wheelFilter");Message msg=Message.Create(canvas.Handle,0x20a,(IntPtr)((120<<16)|8),(IntPtr)((p.Y<<16)|(p.X&65535)));zoom=timeline.Zoom;bool consumed=filter.PreFilterMessage(ref msg);lines.Add("WHEEL consumed="+consumed+" mods="+Control.ModifierKeys+" cursor="+Cursor.Position+" expected="+p+" zoom="+zoom+"->"+timeline.Zoom+" focus="+(Form.ActiveForm==null?"null":Form.ActiveForm.Text));Check(consumed&&timeline.Zoom>zoom&&settings.UiScale==scale,"Actual wheel filter did not route to hovered editor.");keys[18]=128;SetKeyboardState(keys);Check(filter.PreFilterMessage(ref msg)&&settings.UiScale==scale+1,"Ctrl+Alt wheel did not scale workspace 1%.");settings.UiScale=scale;Call(form,"ApplyUiScale");Call(form,"ApplyAdvancedScale");}finally{SetKeyboardState(original);Cursor.Position=cursor;}});
 Test("Captured playhead drag seeks continuously and pans camera at the editing edge",()=>{timeline.ScrollHorizontalTo(0);timeline.SetZoom(32);float header=(int)Field(canvas,"HeaderWidth");Mouse(canvas,0x201,header+64,15,1);double start=(double)Field(form,"_cursorBeat");Check(canvas.Capture,"Playhead did not capture pointer.");Mouse(canvas,0x200,header+192,15,1);double next=(double)Field(form,"_cursorBeat");Check(next>start+2,"Drag did not update playback position.");Mouse(canvas,0x200,canvas.Width/DisplayScale.For(canvas)-3,15,1);Pump(150);Check(timeline.HorizontalBeat>0,"Playhead edge drag did not pan camera.");Mouse(canvas,0x202,header+192,15);Check(!canvas.Capture,"Playhead capture did not release.");});
 Test("Track-header and piano-keyboard resize work six pixels away from divider",()=>{int header=(int)Field(canvas,"HeaderWidth");Mouse(canvas,0x201,header+6,70,1);Mouse(canvas,0x200,header+36,70,1);Mouse(canvas,0x202,header+36,70);Check((int)Field(canvas,"HeaderWidth")>header+20,"Track header hit area too narrow.");Call(form,"AddRegion");var p=Project(form);var t=p.Tracks.First(x=>x.Type==TrackType.Midi);var r=t.Regions.First();Call(form,"Select",(Guid?)t.Id,(Guid?)r.Id);Call(form,"ExecuteCommand",AppCommand.ShowPianoRoll);Pump(60);var piano=(PianoRollEditor)Field(form,"_pianoRoll");var pc=(Control)Field(piano,"_canvas");int key=(int)Field(pc,"KeyWidth");Mouse(pc,0x201,key+6,55,1);Mouse(pc,0x200,key+30,55,1);Mouse(pc,0x202,key+30,55);Check((int)Field(pc,"KeyWidth")==key+30,"Piano divider did not resize.");int ppb=(int)Field(pc,"PixelsPerBeat");piano.NavigateWheel(pc.PointToScreen(new Point(pc.Width/2,55)),120,Keys.Control);Check((int)Field(pc,"PixelsPerBeat")>ppb,"Piano local zoom failed.");});
 Test("WAV and Standard MIDI file-drop events import real content at the dropped musical position",()=>{string wave=Path.Combine(root,"drop.wav");if(File.Exists(wave))File.Delete(wave);using(var writer=new ExportWaveWriter(wave,48000,1,24,false)){float[] b=new float[2400];for(int i=0;i<b.Length;i++)b[i]=(float)(.1*Math.Sin(2*Math.PI*440*i/48000));writer.Write(b,0,b.Length);}string midi=Path.Combine(root,"drop.mid");File.WriteAllBytes(midi,new byte[]{77,84,104,100,0,0,0,6,0,0,0,1,1,224,77,84,114,107,0,0,0,13,0,144,60,96,131,96,128,60,0,0,255,47,0});var data=new DataObject(DataFormats.FileDrop,new[]{wave,midi});Point drop=canvas.PointToScreen(new Point(canvas.Width-130,100));var enter=new DragEventArgs(data,0,drop.X,drop.Y,DragDropEffects.Copy,DragDropEffects.None);Call(canvas,"OnDragEnter",enter);Check(enter.Effect==DragDropEffects.Copy,"File-drop handler rejected supported files.");int regions=Project(form).Tracks.Sum(t=>t.Regions.Count);Call(canvas,"OnDragDrop",new DragEventArgs(data,0,drop.X,drop.Y,DragDropEffects.Copy,DragDropEffects.Copy));var sw=Stopwatch.StartNew();while((bool)Field(form,"_importing")&&sw.ElapsedMilliseconds<4000)Pump(20);var project=Project(form);Check(project.Tracks.Sum(t=>t.Regions.Count)==regions+2,"Drop did not import two real regions: before="+regions+" after="+project.Tracks.Sum(t=>t.Regions.Count)+" status="+((ToolStripStatusLabel)Field(form,"_statusLabel")).Text);Check(project.Tracks.Any(t=>t.Type==TrackType.Audio&&t.Regions.Any(r=>r.MediaPath==wave)),"Dropped audio not linked.");Check(project.Tracks.Where(t=>t.Type==TrackType.Midi).SelectMany(t=>t.Regions).Any(r=>r.Notes.Any(n=>n.Pitch==60)),"Dropped MIDI notes not imported.");lines.Add("NOTE file-drop verification dispatches native-control DragEnter/DragDrop events; Explorer physical drag NOT RUN.");});
 Test("Musical Typing key-up / repeat / focus guards and Record/Stop preserve performed notes",()=>{Call(form,"ToggleSoftwareKeyboard");Pump(100);var keyboard=(SoftwareKeyboard)Field(form,"_softwareKeyboard");form.Activate();timeline.Focus();Pump(80);var project=Project(form);var t=project.Tracks.First(x=>x.Type==TrackType.Midi&&x.Armed);int before=t.Regions.Count;Call(form,"SetCursorBeat",0.0);var bar=(Control)Field(form,"_controlBar");bar.Refresh();var hits=(Dictionary<AppCommand,Rectangle>)Field(bar,"_hits");Rectangle record=hits[AppCommand.Record];Click(bar,record.X+record.Width/2,record.Y+record.Height/2);Check((bool)Field(form,"_recording"),"Actual Record button did not start software-MIDI capture.");form.Activate();timeline.Focus();Pump(30);Message down=Message.Create(timeline.Handle,0x100,(IntPtr)Keys.A,IntPtr.Zero);Check(keyboard.PreFilterMessage(ref down),"Music key was not handled.");keyboard.PreFilterMessage(ref down);Check(keyboard.HeldCount==1,"Auto-repeat duplicated note-on.");Pump(110);Message up=Message.Create(timeline.Handle,0x101,(IntPtr)Keys.A,IntPtr.Zero);Check(keyboard.PreFilterMessage(ref up)&&keyboard.HeldCount==0,"Key-up left a stuck note.");Rectangle stop=hits[AppCommand.Stop];Click(bar,stop.X+stop.Width/2,stop.Y+stop.Height/2);Check(!(bool)Field(form,"_recording")&&t.Regions.Count==before+1&&t.Regions.Last().Notes.Count==1,"Record stop did not preserve one real software note.");Capture(form,"recorded-midi");keyboard.Close();Pump(40);form.Activate();timeline.Focus();Message toggle=Message.Create(form.Handle,0x100,(IntPtr)Keys.K,IntPtr.Zero);Call(form,"ProcessCmdKey",new object[]{toggle,Keys.Control|Keys.K});var once=(SoftwareKeyboard)Field(form,"_softwareKeyboard");Check(once!=null&&!once.IsDisposed,"Ctrl+K did not open Musical Typing.");toggle.LParam=new IntPtr(1L<<30);Call(form,"ProcessCmdKey",new object[]{toggle,Keys.Control|Keys.K});Check(Object.ReferenceEquals(once,Field(form,"_softwareKeyboard"))&&!once.IsDisposed,"Held Ctrl+K repeatedly toggled the keyboard.");once.Activate();Pump(30);Message play=Message.Create(once.Handle,0x100,(IntPtr)Keys.Space,IntPtr.Zero);Call(once,"ProcessCmdKey",new object[]{play,Keys.Space});Check(((ArrangementEngine)Field(form,"_engine")).Playing,"Floating keyboard did not forward transport Space.");Message stopKey=Message.Create(once.Handle,0x100,(IntPtr)Keys.NumPad0,IntPtr.Zero);Call(once,"ProcessCmdKey",new object[]{stopKey,Keys.NumPad0});Check(!((ArrangementEngine)Field(form,"_engine")).Playing,"Floating keyboard did not forward Stop.");toggle.LParam=IntPtr.Zero;Call(once,"ProcessCmdKey",new object[]{toggle,Keys.Control|Keys.K});Check(once.IsDisposed,"Ctrl+K did not close focused floating keyboard.");});
 Test("1280x800 / 100% and 150% workspace retains full button rows and usable arrangement",()=>{form.WindowState=FormWindowState.Normal;form.Size=new Size(1280,800);settings.UiScale=100;Call(form,"ApplyUiScale");Call(form,"ApplyAdvancedScale");Pump(80);Capture(form,"1280x800");Check(timeline.Width>280,"Timeline clipped at 1280.");settings.UiScale=150;Call(form,"ApplyUiScale");Call(form,"ApplyAdvancedScale");Pump(80);Check(timeline.Width>220,"Timeline clipped at 150%.");Capture(form,"1280x800-workspace150");settings.UiScale=100;Call(form,"ApplyUiScale");Call(form,"ApplyAdvancedScale");form.WindowState=FormWindowState.Maximized;});
 Test("Four localized welcome / about / main windows and six effect editors render without exceptions",()=>{foreach(string language in new[]{"en-US","de-DE","ja-JP","ko-KR"}){Call(form,"ChangeLanguage",language);using(var splash=new SplashForm()){splash.Show(form);UiText.Apply(splash);Capture(splash,"splash-"+language);splash.Close();}using(var quick=new QuickStartForm(new List<RecoveryItem>(),null)){quick.Show(form);UiText.Apply(quick);Capture(quick,"quickstart-"+language);quick.Close();}UiText.Apply(form);Capture(form,"main-"+language);using(var closeAbout=new System.Windows.Forms.Timer{Interval=100}){closeAbout.Tick+=delegate{closeAbout.Stop();var about=Application.OpenForms.Cast<Form>().Last(x=>x!=form);UiText.Apply(about);Capture(about,"about-"+language);about.Close();};closeAbout.Start();Call(form,"ShowAbout");}}Call(form,"ChangeLanguage","en-US");foreach(string name in StockEffects.Names){var slot=StockEffects.Create(Project(form).Tracks[0].Id,name);using(var fx=new StockEffectEditor(slot,x=>{},()=>new StockEffectProcessor())){fx.Show(form);UiText.Apply(fx);Capture(fx,"effect-"+name.Replace(" ","-"));fx.Close();}}});
 Test("Slop Pitch Timing analyzes PCM, edits markers and returns a new undoable take",()=>{string f=Path.Combine(root,"timing-audio.wav");float[] audio=new float[72000];for(int n=0;n<3;n++)for(int j=0;j<600;j++)audio[n*24000+j]=(float)(.4*Math.Exp(-j/100.0)*Math.Sin(j*1.3));using(var writer=new ExportWaveWriter(f,48000,1,24,false))writer.Write(audio,0,audio.Length);var t=Project(form).Tracks.First(x=>x.Type==TrackType.Audio);var import=form.ImportDroppedFiles(new[]{f},t.Id,0);var wait=Stopwatch.StartNew();while(!import.IsCompleted&&wait.ElapsedMilliseconds<4000)Pump(20);Check(import.IsCompleted,"Timing fixture import timed out.");var r=t.Regions.Last();Call(form,"Select",(Guid?)t.Id,(Guid?)r.Id);Call(form,"ExecuteCommand",AppCommand.ShowPitch);var pitch=(Control)Field(form,"_pitch");Mouse(pitch,0x201,230,15,1);Mouse(pitch,0x202,230,15);Check((bool)Field(pitch,"_timingMode"),"Timing tab did not switch.");Call(pitch,"Analyze");wait.Restart();while((bool)Field(pitch,"_busy")&&wait.ElapsedMilliseconds<5000)Pump(20);var timing=(TimingAnalysis)Field(pitch,"_timing");var map=(List<TimingMarker>)Field(pitch,"_map");Check(timing!=null&&map.Count>2,"Editor analysis did not create timing markers.");int logicalWidth=(int)(pitch.Width/DisplayScale.For(pitch));double duration=Math.Max(timing.Duration,map.Last().TargetSeconds),old=map[1].TargetSeconds;int markerX=16+(int)Math.Round(old/duration*(logicalWidth-32));Mouse(pitch,0x201,markerX,100,1);Mouse(pitch,0x200,markerX+14,100,1);Mouse(pitch,0x202,markerX+14,100);Check(map[1].TargetSeconds>old,"Marker did not drag.");Capture(form,"timing-mode");string rendered=Path.Combine(root,"timing-render.wav");timing.Save(rendered,map);int before=t.Regions.Count;((Action<string>)Field(pitch,"Baked"))(rendered);Check(t.Regions.Count==before+1&&r.Muted&&t.Regions.Last().MediaPath==rendered,"Rendered take did not replace audible original.");Call(form,"Undo");Check(t.Regions.Count==before&&!r.Muted,"Timing render undo failed.");});
 Test("Plug-in Manager filters actual discoveries and displays bundled DSP without mocks",()=>{PluginCatalog.Items=new List<PluginDescriptor>();foreach(string format in new[]{"vst3","clap"})PluginCatalog.Items.AddRange(NativePlugin.Scan(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"TestFixtures","FixtureGain."+format)));using(var browser=new PluginBrowserDialog(new string[0])){browser.Show(form);Pump(50);var list=(ListView)Field(browser,"_list");Check(list.Items.Count==8,"Catalog did not show 2 real test plugins and 6 stock effects.");Capture(browser,"plugin-manager");((ListBox)Field(browser,"_category")).SelectedIndex=5;Check(list.Items.Count==6,"Built-in filter incorrect.");((TextBox)Field(browser,"_search")).Text="Limiter";Check(list.Items.Count==1,"Search did not filter real DSP catalog.");browser.Close();}});
 Test("Optional falling-region view is reversible with Space and never mutates project data",()=>{var before=ProjectFactory.Clone(Project(form));Call(form,"StartMayhem");Pump(220);Check(Field(form,"_mayhem")!=null,"Mayhem did not start.");Capture(form,"optional-mayhem");Message key=Message.Create(form.Handle,0x100,(IntPtr)Keys.Space,IntPtr.Zero);object[] parameters={key,Keys.Space};Call(form,"ProcessCmdKey",parameters);Check(Field(form,"_mayhem")==null&&ProjectFile.Equivalent(before,Project(form)),"Space did not restore unchanged project.");});
 Test("Saving and reopening retains imported audio, MIDI performance and timeline editing",()=>{string save=Path.Combine(root,"gui-edited.slopdaw");Check((bool)Call(form,"SaveToPath",save),"Save failed.");var loaded=ProjectFile.Load(save);Check(ProjectFile.Equivalent(Project(form),loaded),"Project content changed on reopening.");Call(form,"OpenProjectPath",save);Capture(form,"reopened-project");});
 CloseMain(form);}
 lines.Add("NOT RUN physical multi-monitor DPI transition and physical controller.");if(uiErrors.Count>0)lines.Add("UI EXCEPTIONS "+String.Join("\n",uiErrors.Select(x=>x.ToString()).ToArray()));File.WriteAllLines(Path.Combine(root,"v7-gui-tests.txt"),lines);foreach(string line in lines)Console.WriteLine(line);return failed==0?0:1;}
